# ==============================================================================
# Android Evrensel Debloat & Sistem Optimizasyon Araci v2.0.1
# Tum Android Cihazlar & Markalar (AOSP, Samsung, Xiaomi/MIUI/HyperOS,
# OPPO/Realme/OnePlus, Huawei/Honor, Motorola, Vivo, Transsion, Sony, Asus)
# Uyumluluk: Windows PowerShell 5.1+ ve PowerShell 7+
# ==============================================================================

<#
.SYNOPSIS
    Android cihazlar icin evrensel debloat, sistem optimizasyonu, yedekleme ve geri yukleme araci.
.EXAMPLE
    .\Android-Universal-Debloat.ps1
.EXAMPLE
    .\Android-Universal-Debloat.ps1 -Tier 1 -DryRun
.EXAMPLE
    .\Android-Universal-Debloat.ps1 -Tier 2 -Optimize -NonInteractive
#>

[CmdletBinding()]
param(
    [ValidateSet(0, 1, 2, 3)]
    [int]$Tier = 0,
    [switch]$DryRun,
    [switch]$Optimize,
    [string]$PrivateDns,
    [string]$RestoreBackup,
    [string]$Serial,
    [switch]$NonInteractive,
    [switch]$KillAdbOnExit
)

$ErrorActionPreference = "Continue"

$script:Version = "2.0.1"
$script:Adb = $null
$script:AdbSource = ""
$script:DeviceSerial = $null
$script:DeviceInfo = $null
$script:LastAdbExitCode = 0
$script:DataDir = $null
$script:AdbDir = $null
$script:BackupDir = $null
$script:LogDir = $null
$script:WhitelistPath = $null
$script:LogFile = $null
$script:InstalledPackages = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
$script:EnabledPackages = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
$script:Whitelist = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)

# ------------------------------------------------------------------------------
# 1. Klasor Yonetimi, Loglama ve Yardimci Araclar
# ------------------------------------------------------------------------------

function Get-ScriptDirectory {
    if ($PSScriptRoot) {
        return $PSScriptRoot
    }
    return (Get-Location).Path
}

function Get-SafeFileName {
    param([string]$Text)
    if (-not $Text) { return "Unknown" }
    $clean = $Text -replace '[^a-zA-Z0-9_-]', '_'
    $clean = $clean -replace '_+', '_'
    $clean = $clean.Trim('_')
    if (-not $clean) { return "Unknown" }
    return $clean
}

function Initialize-Workspace {
    $candidates = @(
        (Join-Path (Get-ScriptDirectory) "AndroidDebloatData")
    )
    if ($env:LOCALAPPDATA) {
        $candidates += (Join-Path $env:LOCALAPPDATA "AndroidDebloatData")
    }
    if ($env:TEMP) {
        $candidates += (Join-Path $env:TEMP "AndroidDebloatData")
    }

    foreach ($dir in $candidates) {
        try {
            if (-not (Test-Path $dir)) {
                [void](New-Item -ItemType Directory -Path $dir -Force -ErrorAction Stop)
            }
            $testFile = Join-Path $dir ".write_test"
            [System.IO.File]::WriteAllText($testFile, "ok")
            Remove-Item $testFile -Force -ErrorAction SilentlyContinue

            $script:DataDir = $dir
            $script:AdbDir = Join-Path $dir "adb"
            $script:BackupDir = Join-Path $dir "backups"
            $script:LogDir = Join-Path $dir "logs"
            $script:WhitelistPath = Join-Path $dir "whitelist.txt"

            foreach ($sub in @($script:AdbDir, $script:BackupDir, $script:LogDir)) {
                if (-not (Test-Path $sub)) {
                    [void](New-Item -ItemType Directory -Path $sub -Force -ErrorAction Stop)
                }
            }

            if (-not (Test-Path $script:WhitelistPath)) {
                $wlHeader = @(
                    "# Android Universal Debloat - Haric Tutulan Paketler (Whitelist)",
                    "# Her satira bir paket adi yazin. Bu listedeki paketlere dokunulmaz.",
                    "# Ornek: com.google.android.apps.docs"
                )
                [System.IO.File]::WriteAllLines($script:WhitelistPath, $wlHeader)
            }
            return $true
        } catch {
            continue
        }
    }
    return $false
}

function Get-DeviceFilePrefix {
    if (-not $script:DeviceInfo) {
        return "NoDevice"
    }
    $brand = Get-SafeFileName $script:DeviceInfo.Brand
    $model = Get-SafeFileName $script:DeviceInfo.Model
    $ser = Get-SafeFileName $script:DeviceInfo.Serial
    if ($model.ToLower().StartsWith($brand.ToLower())) {
        return "${model}_${ser}"
    }
    return "${brand}_${model}_${ser}"
}

function Initialize-SessionLog {
    if (-not $script:LogDir) { return }
    $prefix = Get-DeviceFilePrefix
    $stamp = Get-Date -Format "yyyyMMdd_HHmmss"
    $script:LogFile = Join-Path $script:LogDir "${prefix}_${stamp}.log"
    Write-Log "=== Oturum Basladi (v$($script:Version)) ==="
    if ($script:DeviceInfo) {
        Write-Log "Cihaz: $($script:DeviceInfo.Manufacturer) $($script:DeviceInfo.Model) | Serial: $($script:DeviceInfo.Serial) | Android $($script:DeviceInfo.Android) (SDK $($script:DeviceInfo.Sdk))"
    }
}

function Write-Log {
    param(
        [string]$Message,
        [string]$Level = "INFO"
    )
    if (-not $script:LogFile) { return }
    try {
        $ts = Get-Date -Format "yyyy-MM-dd HH:mm:ss"
        Add-Content -Path $script:LogFile -Value "[$ts] [$Level] $Message" -ErrorAction SilentlyContinue
    } catch { }
}

function Read-Whitelist {
    $script:Whitelist.Clear()
    if (-not $script:WhitelistPath -or -not (Test-Path $script:WhitelistPath)) {
        return
    }
    foreach ($line in (Get-Content -Path $script:WhitelistPath -ErrorAction SilentlyContinue)) {
        $t = $line.Trim()
        if ($t -and -not $t.StartsWith("#")) {
            [void]$script:Whitelist.Add($t)
        }
    }
}

# ------------------------------------------------------------------------------
# 2. ADB Kurulumu (Oncelik: Yerel -> Internetten Guncel Indirme -> Gomulu Yedek)
# ------------------------------------------------------------------------------

function Test-AdbFolderComplete {
    param([string]$AdbExePath)
    if (-not $AdbExePath -or -not (Test-Path $AdbExePath)) {
        return $false
    }
    $dir = Split-Path -Path $AdbExePath -Parent
    return ((Test-Path (Join-Path $dir "AdbWinApi.dll")) -and (Test-Path (Join-Path $dir "AdbWinUsbApi.dll")))
}

function Install-OnlineAdb {
    param([string]$TargetDir)

    $url = "https://dl.google.com/android/repository/platform-tools-latest-windows.zip"
    $tempZip = Join-Path $TargetDir "platform-tools-temp.zip"

    Write-Host "Internet baglantisi kontrol ediliyor (Guncel Google Platform-Tools)..." -ForegroundColor Cyan

    try {
        [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12
    } catch { }

    try {
        $req = [System.Net.WebRequest]::Create($url)
        $req.Method = "HEAD"
        $req.Timeout = 5000
        $resp = $req.GetResponse()
        $resp.Close()
    } catch {
        Write-Host "[i] Internet baglantisi yok veya Google sunucusuna erisilemedi. Gomulu ADB kullanilacak." -ForegroundColor Yellow
        return $null
    }

    $wc = $null
    $zip = $null
    try {
        Add-Type -AssemblyName System.IO.Compression.FileSystem -ErrorAction Stop
        Write-Host "Guncel ADB indiriliyor: $url" -ForegroundColor Cyan
        $wc = New-Object System.Net.WebClient
        $wc.DownloadFile($url, $tempZip)

        if (-not (Test-Path $tempZip)) {
            throw "Indirilen zip dosyasi bulunamadi."
        }

        $wanted = @("adb.exe", "AdbWinApi.dll", "AdbWinUsbApi.dll")
        $zip = [System.IO.Compression.ZipFile]::OpenRead($tempZip)
        foreach ($entry in $zip.Entries) {
            if ([string]::IsNullOrEmpty($entry.Name)) { continue }
            if ($wanted -contains $entry.Name) {
                $destPath = Join-Path $TargetDir $entry.Name
                $inStream = $null
                $outStream = $null
                try {
                    $inStream = $entry.Open()
                    $outStream = New-Object System.IO.FileStream($destPath, [System.IO.FileMode]::Create, [System.IO.FileAccess]::Write, [System.IO.FileShare]::None)
                    $inStream.CopyTo($outStream)
                } finally {
                    if ($outStream) { $outStream.Dispose() }
                    if ($inStream) { $inStream.Dispose() }
                }
            }
        }
        $zip.Dispose()
        $zip = $null

        $adbExe = Join-Path $TargetDir "adb.exe"
        if (Test-AdbFolderComplete -AdbExePath $adbExe) {
            Write-Host "[OK] Guncel ADB internetten indirildi ve kuruldu: $TargetDir" -ForegroundColor Green
            $script:AdbSource = "Online (Google Platform-Tools)"
            return $adbExe
        }
    } catch {
        Write-Host "[UYARI] Internetten ADB indirilemedi: $($_.Exception.Message)" -ForegroundColor Yellow
    } finally {
        if ($zip) { $zip.Dispose() }
        if ($wc) { $wc.Dispose() }
        if (Test-Path $tempZip) {
            Remove-Item $tempZip -Force -ErrorAction SilentlyContinue
        }
    }

    return $null
}

function Expand-EmbeddedAdb {
    param([string]$TargetDir)

    if (-not $script:EmbeddedAdbZipBase64 -or $script:EmbeddedAdbZipBase64 -match "__EMBEDDED_ADB_ZIP_BASE64__") {
        Write-Host "[HATA] Gomulu ADB verisi betik icinde bulunamadi." -ForegroundColor Red
        return $null
    }

    try {
        Add-Type -AssemblyName System.IO.Compression -ErrorAction Stop
    } catch {
        Write-Host "[HATA] System.IO.Compression yuklenemedi: $($_.Exception.Message)" -ForegroundColor Red
        return $null
    }

    $zipBytes = [System.Convert]::FromBase64String($script:EmbeddedAdbZipBase64)
    $ms = $null
    $zip = $null

    try {
        if (-not (Test-Path $TargetDir)) {
            [void](New-Item -ItemType Directory -Path $TargetDir -Force -ErrorAction Stop)
        }

        $ms = New-Object System.IO.MemoryStream(, $zipBytes)
        $zip = New-Object System.IO.Compression.ZipArchive($ms, [System.IO.Compression.ZipArchiveMode]::Read, $false)

        foreach ($entry in $zip.Entries) {
            if ([string]::IsNullOrEmpty($entry.Name)) { continue }
            $destPath = Join-Path $TargetDir $entry.Name
            $inStream = $null
            $outStream = $null
            try {
                $inStream = $entry.Open()
                $outStream = New-Object System.IO.FileStream($destPath, [System.IO.FileMode]::Create, [System.IO.FileAccess]::Write, [System.IO.FileShare]::None)
                $inStream.CopyTo($outStream)
            } finally {
                if ($outStream) { $outStream.Dispose() }
                if ($inStream) { $inStream.Dispose() }
            }
        }

        $adbExe = Join-Path $TargetDir "adb.exe"
        if (Test-AdbFolderComplete -AdbExePath $adbExe) {
            Write-Host "[OK] Gomulu ADB cikartildi: $TargetDir" -ForegroundColor Green
            $script:AdbSource = "Gomulu (Offline)"
            return $adbExe
        }
    } catch {
        Write-Host "[HATA] Gomulu ADB cikartilamadi ($TargetDir): $($_.Exception.Message)" -ForegroundColor Red
    } finally {
        if ($zip) { $zip.Dispose() }
        if ($ms) { $ms.Dispose() }
    }

    return $null
}

function Find-AdbPath {
    # 1. Oncelik: Tekil veri klasorundeki adb
    $unifiedAdb = Join-Path $script:AdbDir "adb.exe"
    if (Test-AdbFolderComplete -AdbExePath $unifiedAdb) {
        $script:AdbSource = "Yerel ($($script:AdbDir))"
        return $unifiedAdb
    }

    # 2. Sistemde kurulu ve DLL'leri eksiksiz ADB var mi?
    $candidates = @()
    $cmd = Get-Command adb -ErrorAction SilentlyContinue
    if ($cmd -and $cmd.Source) {
        $candidates += $cmd.Source
    }
    $candidates += "C:\platform-tools\adb.exe"
    if ($env:LOCALAPPDATA) {
        $candidates += (Join-Path $env:LOCALAPPDATA "Android\Sdk\platform-tools\adb.exe")
    }

    foreach ($path in $candidates) {
        if (Test-AdbFolderComplete -AdbExePath $path) {
            $script:AdbSource = "Sistem ($path)"
            return $path
        }
    }

    # 3. Internetten guncel ADB indirmeyi dene
    $onlineAdb = Install-OnlineAdb -TargetDir $script:AdbDir
    if ($onlineAdb) {
        return $onlineAdb
    }

    # 4. Internet yoksa veya basarisizsa gomulu ADB'yi cikart
    Write-Host "Gomulu ADB araci cikartiliyor..." -ForegroundColor Yellow
    return (Expand-EmbeddedAdb -TargetDir $script:AdbDir)
}

# ------------------------------------------------------------------------------
# 3. ADB Iletisim & Cihaz Yardimcilari
# ------------------------------------------------------------------------------

function Invoke-Adb {
    param(
        [Parameter(Mandatory = $true)]
        [string[]]$Arguments,
        [switch]$NoDeviceSerial
    )

    $adbArgs = @()
    if (-not $NoDeviceSerial -and $script:DeviceSerial) {
        $adbArgs += "-s"
        $adbArgs += $script:DeviceSerial
    }
    $adbArgs += $Arguments

    $output = & $script:Adb @adbArgs 2>&1
    $script:LastAdbExitCode = $LASTEXITCODE

    if ($null -eq $output) {
        return @()
    }
    return @($output | ForEach-Object { $_.ToString() })
}

function Test-DeviceConnected {
    if (-not $script:DeviceSerial) { return $false }
    $out = Invoke-Adb -Arguments @("get-state")
    $state = ($out -join "").Trim()
    return ($script:LastAdbExitCode -eq 0 -and $state -eq "device")
}

function Assert-DeviceConnected {
    if (Test-DeviceConnected) { return $true }
    Write-Host ""
    Write-Host "[HATA] Cihaz baglantisi kesilmis! Lutfen USB kablosunu kontrol edip [9] ile yeniden baglanin." -ForegroundColor Red
    Write-Log "Cihaz baglantisi kesildi ($($script:DeviceSerial))" "ERROR"
    return $false
}

function Get-DeviceProp {
    param([string]$PropName)
    $res = Invoke-Adb -Arguments @("shell", "getprop", $PropName)
    if ($script:LastAdbExitCode -ne 0) { return "Bilinmiyor" }
    $val = ($res -join "").Trim()
    if (-not $val -or $val -match "^error:") { return "Bilinmiyor" }
    return $val
}

function Get-DeviceMetrics {
    $battery = "?"
    $freeSpace = "?"

    $batLines = Invoke-Adb -Arguments @("shell", "dumpsys", "battery")
    if ($script:LastAdbExitCode -eq 0) {
        foreach ($line in $batLines) {
            if ($line -match "^\s*level:\s*(\d+)") {
                $battery = "$($Matches[1])%"
                break
            }
        }
    }

    $dfLines = Invoke-Adb -Arguments @("shell", "df", "-h", "/data")
    if ($script:LastAdbExitCode -eq 0) {
        foreach ($line in $dfLines) {
            if ($line -match "\s+(\S+)\s+\S+\s+(\S+)\s+\d+%\s+/data") {
                $freeSpace = $Matches[2]
                break
            }
        }
    }

    return [PSCustomObject]@{
        Battery   = $battery
        FreeSpace = $freeSpace
    }
}

function Get-DevicePackageState {
    if (-not (Test-DeviceConnected)) {
        Write-Host "[UYARI] Cihaz bagli olmadigi icin paket listesi okunamadi." -ForegroundColor Yellow
        return $false
    }

    $newInstalled = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    $newEnabled = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)

    $allLines = Invoke-Adb -Arguments @("shell", "pm", "list", "packages", "--user", "0")
    if ($script:LastAdbExitCode -ne 0) {
        Write-Host "[HATA] Paket listesi okunamadi (ADB hata kodu: $($script:LastAdbExitCode))." -ForegroundColor Red
        return $false
    }

    foreach ($line in $allLines) {
        $trimmed = $line.Trim()
        if ($trimmed -match "^package:(.+)$") {
            [void]$newInstalled.Add($Matches[1].Trim())
        }
    }

    if ($newInstalled.Count -eq 0) {
        Write-Host "[UYARI] Cihazdan hic paket okunamadi. Baglanti veya izin sorunu olabilir." -ForegroundColor Yellow
        return $false
    }

    $enabledLines = Invoke-Adb -Arguments @("shell", "pm", "list", "packages", "-e", "--user", "0")
    foreach ($line in $enabledLines) {
        $trimmed = $line.Trim()
        if ($trimmed -match "^package:(.+)$") {
            [void]$newEnabled.Add($Matches[1].Trim())
        }
    }

    if ($newEnabled.Count -eq 0 -and $newInstalled.Count -gt 0) {
        $enabledFallback = Invoke-Adb -Arguments @("shell", "pm", "list", "packages", "-e")
        foreach ($line in $enabledFallback) {
            $trimmed = $line.Trim()
            if ($trimmed -match "^package:(.+)$") {
                [void]$newEnabled.Add($Matches[1].Trim())
            }
        }
        if ($newEnabled.Count -eq 0) {
            foreach ($p in $newInstalled) { [void]$newEnabled.Add($p) }
        }
    }

    $script:InstalledPackages = $newInstalled
    $script:EnabledPackages = $newEnabled
    return $true
}

function Connect-WirelessDevice {
    Write-Host ""
    Write-Host "=== Kablosuz ADB (Android 11+ Wireless Debugging) ===" -ForegroundColor Cyan
    Write-Host "  Telefon: Ayarlar > Gelistirici secenekleri > Kablosuz hata ayiklama" -ForegroundColor Gray
    Write-Host "  [1] Ilk kez eslestir (Pair) + Baglan"
    Write-Host "  [2] Sadece Baglan (IP:Port)"
    Write-Host "  [0] Iptal"
    $wChoice = Read-Host "Seciminiz"

    if ($wChoice -eq "1") {
        $pairAddr = Read-Host "Eslestirme IP:Port (orn. 192.168.1.50:37123)"
        $pairCode = Read-Host "6 haneli eslestirme kodu"
        if ($pairAddr -and $pairCode) {
            $out = Invoke-Adb -Arguments @("pair", $pairAddr, $pairCode) -NoDeviceSerial
            Write-Host ($out -join "`n") -ForegroundColor Gray
        }
    }

    if ($wChoice -eq "1" -or $wChoice -eq "2") {
        $connAddr = Read-Host "Baglanti IP:Port (orn. 192.168.1.50:41234)"
        if ($connAddr) {
            $out = Invoke-Adb -Arguments @("connect", $connAddr) -NoDeviceSerial
            Write-Host ($out -join "`n") -ForegroundColor Cyan
        }
    }
}

function Connect-Device {
    param([string]$PreferredSerial)

    while ($true) {
        $script:DeviceSerial = $null
        $rawDevices = Invoke-Adb -Arguments @("devices") -NoDeviceSerial

        $ready = @()
        $unauthorized = @()
        $offline = @()

        foreach ($line in $rawDevices) {
            $t = $line.Trim()
            if (-not $t -or $t.StartsWith("List of devices") -or $t.StartsWith("*")) {
                continue
            }
            if ($t -match "^(\S+)\s+device$") {
                $ready += $Matches[1]
            } elseif ($t -match "^(\S+)\s+unauthorized$") {
                $unauthorized += $Matches[1]
            } elseif ($t -match "^(\S+)\s+offline$") {
                $offline += $Matches[1]
            }
        }

        if ($ready.Count -eq 0) {
            Write-Host ""
            Write-Host "[!] Hazir durumda bagli Android cihaz bulunamadi." -ForegroundColor Red
            if ($unauthorized.Count -gt 0) {
                Write-Host "    Yetkilendirme bekleyen cihaz: $($unauthorized -join ', ')" -ForegroundColor Yellow
                Write-Host "    Telefon ekraninda 'USB hata ayiklamaya izin ver' penceresini onaylayin." -ForegroundColor Yellow
            }
            if ($offline.Count -gt 0) {
                Write-Host "    Cevrimdisi (offline) cihaz: $($offline -join ', ')" -ForegroundColor Yellow
                Write-Host "    USB kablosunu cikarip yeniden takin." -ForegroundColor Yellow
            }
            Write-Host "    Ayarlar > Gelistirici secenekleri > USB hata ayiklama acik olmalidir." -ForegroundColor Gray
            if ($NonInteractive) {
                return $false
            }
            $choice = Read-Host "Yeniden dene [R], Kablosuz baglan [W], Cikis [0]"
            if ($choice -eq "0") { return $false }
            if ($choice -match "^[Ww]$") {
                Connect-WirelessDevice
            }
            continue
        }

        if ($PreferredSerial -and ($ready -contains $PreferredSerial)) {
            $script:DeviceSerial = $PreferredSerial
        } elseif ($ready.Count -gt 1) {
            if ($NonInteractive) {
                $script:DeviceSerial = $ready[0]
            } else {
                Write-Host ""
                Write-Host "Birden fazla cihaz bagli. Hedef cihazi secin:" -ForegroundColor Cyan
                for ($i = 0; $i -lt $ready.Count; $i++) {
                    $ser = $ready[$i]
                    $m = ((& $script:Adb -s $ser shell getprop ro.product.model 2>&1) -join "").Trim()
                    Write-Host "  [$($i + 1)] $ser ($m)"
                }
                $sel = Read-Host "Seciminiz (1-$($ready.Count))"
                $idx = 0
                if ([int]::TryParse($sel, [ref]$idx) -and $idx -ge 1 -and $idx -le $ready.Count) {
                    $script:DeviceSerial = $ready[$idx - 1]
                } else {
                    Write-Host "Gecersiz secim, ilk cihaz secildi." -ForegroundColor Yellow
                    $script:DeviceSerial = $ready[0]
                }
            }
        } else {
            $script:DeviceSerial = $ready[0]
        }

        $manufacturer = Get-DeviceProp "ro.product.manufacturer"
        $brand = Get-DeviceProp "ro.product.brand"
        $model = Get-DeviceProp "ro.product.model"
        $androidVer = Get-DeviceProp "ro.build.version.release"
        $sdkVer = Get-DeviceProp "ro.build.version.sdk"

        $sdkInt = 0
        [void][int]::TryParse($sdkVer, [ref]$sdkInt)

        $script:DeviceInfo = [PSCustomObject]@{
            Serial       = $script:DeviceSerial
            Manufacturer = $manufacturer
            Brand        = $brand
            Model        = $model
            Android      = $androidVer
            Sdk          = $sdkVer
            SdkInt       = $sdkInt
        }

        Initialize-SessionLog
        Write-Host "Cihaz paket listesi okunuyor..." -ForegroundColor DarkGray
        [void](Get-DevicePackageState)
        return $true
    }
}

# ------------------------------------------------------------------------------
# 4. Katmanli Paket Katalogu (Bootloop Riski Olan Sistem Paketleri Haric)
# ------------------------------------------------------------------------------

function Add-CatalogItems {
    param(
        [System.Collections.Generic.List[object]]$List,
        [string[]]$Packages,
        [string]$Action,
        [int]$Tier,
        [string]$Group,
        [hashtable]$Descriptions = @{}
    )
    foreach ($p in $Packages) {
        $desc = if ($Descriptions.ContainsKey($p)) { $Descriptions[$p] } else { $Group }
        $List.Add([PSCustomObject]@{
            Pkg    = $p
            Action = $Action
            Tier   = $Tier
            Group  = $Group
            Desc   = $desc
        })
    }
}

function Get-PackageCatalog {
    $catalog = New-Object 'System.Collections.Generic.List[object]'

    $descMap = @{
        "com.google.android.apps.docs"               = "Google Drive (Bulut Depolama - KRITIK)"
        "com.google.android.projection.gearhead"     = "Android Auto (Arac Baglantisi)"
        "com.samsung.android.app.watchmanager"       = "Galaxy Wearable (Akilli Saat/Kulaklik)"
        "com.samsung.android.oneconnect"             = "Samsung SmartThings (Akilli Ev/Tag)"
        "com.sec.android.app.shealth"                = "Samsung Health (Saglik Takibi)"
        "com.google.ar.core"                         = "Google ARCore (Artirilmis Gerceklik)"
        "com.samsung.android.game.gos"               = "Samsung Game Optimizing Service"
        "com.xiaomi.joyose"                          = "Xiaomi Joyose (Oyun/Termal Servisi)"
        "com.miui.vsimcore"                          = "Xiaomi Sanal SIM / eSIM Servisi"
        "com.google.android.apps.restore"            = "Google Veri Aktarma / Yedek Geri Yukleme"
        "com.google.android.apps.youtube.music"      = "YouTube Music"
        "com.google.android.apps.bard"               = "Google Gemini"
        "com.google.android.apps.googleassistant"    = "Google Asistan"
        "com.google.android.googlequicksearchbox"    = "Google Arama / Lens / Circle to Search"
